window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a5c9a69a72f2ec9f"]={"versions": [{"id": "FIG-a5c9a69a72f2ec9f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Pakete und Entitäten:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code>: Wurzelpaket des AUTOSAR-Modells; aggregiert über das Hauptelement <code>AUTOSAR</code> die Metaklassen der verschiedenen Template-Pakete (erläutert durch eine Notiz).\n</li><li><code>GenericStructure</code>: Grundlegendes Basispaket; enthält Metaklassen, die laut Notiz von allen anderen Top-Level-Paketen aggregiert werden.\n</li><li><code>CommonStructure</code>: Querschnittspaket für wiederverwendbare Grundstrukturen und Basistypen.\n</li><li>Fachliche Template-Pakete: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>ECUResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code> und <code>ECUCParameterDefTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Die gerichteten Abhängigkeiten (gestrichelte Pfeile) stellen Nutzung bzw. Metaklassenaggregation dar:</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> nutzt <code>CommonStructure</code>, <code>ECUResourceTemplate</code> und <code>BswModuleTemplate</code>; steht in wechselseitiger Abhängigkeit zu <code>SystemTemplate</code> und <code>ECUResourceTemplate</code>.\n</li><li><code>SystemTemplate</code> nutzt <code>SWComponentTemplate</code>, <code>ECUResourceTemplate</code> und <code>CommonStructure</code>; steht in wechselseitiger Beziehung zu <code>SWComponentTemplate</code> und <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>ECUResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und steht in wechselseitiger Abhängigkeit zu <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>ECUResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>SWComponentTemplate</code>, zudem besteht die wechselseitige Beziehung zu <code>ECUCDescriptionTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ maßgeblich für die Paketierung, Namensräume und Schichtung des AUTOSAR-Metamodells. Änderungen an den Paketstrukturen oder neuen Abhängigkeiten bedingen Importbeziehungen in XML-Schema-Definitionen (XSD) und den Generatoren des Toolings. Pakete ohne explizite Pfeile unterliegen der globalen Notiz, dass Metaklassen aus <code>GenericStructure</code> aggregiert werden.</p>"}, {"id": "FIG-24228ee64b6300b3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst die Metamodell-Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit erläuternder Notiz zur Aggregation von Metaklassen aus den Template-Paketen durch das Wurzelelement <code>AUTOSAR</code>)\n</li><li><code>GenericStructure</code> (mit erläuternder Notiz rechts neben dem Paket zur Aggregation durch alle Top-Level-Pakete)\n</li><li><code>CommonStructure</code>\n</li><li>Fachspezifische Templates: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>ECUResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>\n</li><li><code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> als isoliert dargestellte Pakete am unteren Rand.\n</li></ul>\n<p class=\"fig-p\">Die gerichteten Abhängigkeiten zwischen den Paketen umfassen:</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> referenziert <code>CommonStructure</code>, <code>ECUResourceTemplate</code>, <code>BswModuleTemplate</code> sowie bidirektional <code>SystemTemplate</code> und <code>ECUResourceTemplate</code>.\n</li><li><code>SystemTemplate</code> referenziert <code>SWComponentTemplate</code>, <code>ECUResourceTemplate</code>, <code>CommonStructure</code> sowie bidirektional <code>SWComponentTemplate</code> und <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> referenziert <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>ECUResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und wechselseitig <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> referenziert <code>CommonStructure</code>, <code>ECUResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> sowie wechselseitig <code>ECUCDescriptionTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ maßgeblich für die Metamodell-Topologie. Mit der Aufnahme von <code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> werden Konzepte für Standardisierungsartefakte und Varianten-/Feature-Modellierung im Gesamtmetamodell verankert. Für Modellierungswerkzeuge definieren die Pakete modulare Namensraumgrenzen.</p>"}, {"id": "FIG-1f628baae465cda6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zum Root-Element <code>AUTOSAR</code>)\n</li><li><code>GenericStructure</code> (mit Notiz zur Aggregation durch alle anderen Top-Level-Pakete)\n</li><li><code>CommonStructure</code>\n</li><li>Fachliche Templates: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>\n</li><li><code>DiagnosticExtract</code>\n</li><li>Untere freistehende Pakete: <code>StandardizationTemplate</code> (links) und <code>FeatureModelTemplate</code> (rechts).\n</li></ul>\n<p class=\"fig-p\">Beziehungen und gerichtete Abhängigkeiten:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticExtract</code> besitzt gerichtete Abhängigkeiten zu <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>SWComponentTemplate</code> steht in wechselseitigen Beziehungen mit <code>SystemTemplate</code> und <code>EcuResourceTemplate</code> und nutzt <code>CommonStructure</code> und <code>BswModuleTemplate</code>.\n</li><li><code>SystemTemplate</code> besitzt wechselseitige Beziehungen zu <code>CommonStructure</code> und <code>SWComponentTemplate</code> und nutzt <code>EcuResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und steht in wechselseitiger Abhängigkeit zu <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> und steht in wechselseitiger Abhängigkeit zu <code>ECUCDescriptionTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für den Aufbau der Spezifikationspakete. Die Etablierung des Pakets <code>DiagnosticExtract</code> verankert Diagnosebeschreibungen als eigenständige Entwurfsschnittstelle zu Software-Komponenten und Systembeschreibung. Die Schreibweise von <code>EcuResourceTemplate</code> folgt der einheitlichen Binnenmajuskel-Konvention für ECU-Metamodellpakete.</p>"}, {"id": "FIG-18b39087236dba09", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zu <code>AUTOSAR</code> als Modellwurzel)\n</li><li><code>GenericStructure</code> (mit Notiz zur allgemeinen Aggregation)\n</li><li><code>CommonStructure</code>\n</li><li>Plattform- und Template-Pakete: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>DiagnosticExtract</code>, <code>AdaptivePlatform</code>\n</li><li>Basis- und Standardisierungspakete: <code>StandardizationTemplate</code>, <code>FeatureModelTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Abhängigkeiten und Verwendungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>AdaptivePlatform</code> besitzt gerichtete Abhängigkeiten zu <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><code>DiagnosticExtract</code> nutzt <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>SWComponentTemplate</code> nutzt <code>CommonStructure</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code> und <code>BswModuleTemplate</code>; von <code>SystemTemplate</code> und <code>EcuResourceTemplate</code> gehen parallele Rückpfeile auf <code>SWComponentTemplate</code> ein.\n</li><li><code>SystemTemplate</code> nutzt <code>SWComponentTemplate</code>, <code>CommonStructure</code> und <code>EcuResourceTemplate</code>; von <code>CommonStructure</code> existiert eine separate Rückbeziehung auf <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> und <code>ECUCDescriptionTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ hochgradig relevant durch die Einführung von <code>AdaptivePlatform</code> in die AUTOSAR-Metamodellarchitektur. Damit wird die methodische und strukturelle Kopplung von Classic Platform und Adaptive Platform auf Metamodellebene formalisiert, insbesondere durch Schnittstellen zu Diagnose, Software-Komponenten und Systembeschreibungen.</p>"}, {"id": "FIG-c7110fe479811a02", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zu <code>AUTOSAR</code> als Modellwurzel)\n</li><li><code>GenericStructure</code> (mit Notiz zur allgemeinen Aggregation)\n</li><li><code>CommonStructure</code>\n</li><li>Plattform- und Template-Pakete: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>DiagnosticExtract</code>, <code>AdaptivePlatform</code>\n</li><li>Basis- und Standardisierungspakete: <code>StandardizationTemplate</code>, <code>FeatureModelTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Abhängigkeiten und Verwendungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>AdaptivePlatform</code> besitzt gerichtete Abhängigkeiten zu <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><code>DiagnosticExtract</code> nutzt <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>SWComponentTemplate</code> nutzt <code>CommonStructure</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code> und <code>BswModuleTemplate</code>; von <code>SystemTemplate</code> und <code>EcuResourceTemplate</code> gehen parallele Rückpfeile auf <code>SWComponentTemplate</code> ein.\n</li><li><code>SystemTemplate</code> nutzt <code>SWComponentTemplate</code>, <code>CommonStructure</code> und <code>EcuResourceTemplate</code>; von <code>CommonStructure</code> existiert eine separate Rückbeziehung auf <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> und <code>ECUCDescriptionTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ hochgradig relevant durch die Einführung von <code>AdaptivePlatform</code> in die AUTOSAR-Metamodellarchitektur. Damit wird die methodische und strukturelle Kopplung von Classic Platform und Adaptive Platform auf Metamodellebene formalisiert, insbesondere durch Schnittstellen zu Diagnose, Software-Komponenten und Systembeschreibungen.</p>"}, {"id": "FIG-9408da1e4f0cdaae", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zu <code>AUTOSAR</code> als Modellwurzel)\n</li><li><code>GenericStructure</code> (mit Notiz zur allgemeinen Aggregation)\n</li><li><code>CommonStructure</code>\n</li><li>Plattform- und Template-Pakete: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>DiagnosticExtract</code>, <code>AdaptivePlatform</code>\n</li><li>Basis- und Standardisierungspakete: <code>StandardizationTemplate</code>, <code>FeatureModelTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Abhängigkeiten und Verwendungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>AdaptivePlatform</code> besitzt gerichtete Abhängigkeiten zu <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><code>DiagnosticExtract</code> nutzt <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>SWComponentTemplate</code> nutzt <code>CommonStructure</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code> und <code>BswModuleTemplate</code>; von <code>SystemTemplate</code> und <code>EcuResourceTemplate</code> gehen parallele Rückpfeile auf <code>SWComponentTemplate</code> ein.\n</li><li><code>SystemTemplate</code> nutzt <code>SWComponentTemplate</code>, <code>CommonStructure</code> und <code>EcuResourceTemplate</code>; von <code>CommonStructure</code> existiert eine separate Rückbeziehung auf <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> und <code>ECUCDescriptionTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ hochgradig relevant durch die Einführung von <code>AdaptivePlatform</code> in die AUTOSAR-Metamodellarchitektur. Damit wird die methodische und strukturelle Kopplung von Classic Platform und Adaptive Platform auf Metamodellebene formalisiert, insbesondere durch Schnittstellen zu Diagnose, Software-Komponenten und Systembeschreibungen.</p>"}, {"id": "FIG-7bbdd92765f5ecdc", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zur Modellwurzel <code>AUTOSAR</code>)\n</li><li><code>GenericStructure</code> (mit Notiz zur universellen Metaklassenaggregation)\n</li><li><code>CommonStructure</code>\n</li><li>Plattform- und Template-Pakete: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>DiagnosticExtract</code>, <code>AdaptivePlatform</code>\n</li><li>Übergreifende und plattformneutrale Pakete: <code>AbstractPlatform</code> (unten links), <code>StandardizationTemplate</code>, <code>FeatureModelTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Abhängigkeiten und Verwendungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>AdaptivePlatform</code> nutzt <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><code>DiagnosticExtract</code> nutzt <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>SWComponentTemplate</code> nutzt <code>CommonStructure</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code> und <code>BswModuleTemplate</code>; <code>SystemTemplate</code> und <code>EcuResourceTemplate</code> verweisen ebenfalls auf <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> und <code>CommonStructure</code> besitzen wechselseitig gerichtete Pfeile; <code>SystemTemplate</code> nutzt zudem <code>EcuResourceTemplate</code> und <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> und <code>ECUCDescriptionTemplate</code>.\n</li><li><code>AbstractPlatform</code>, <code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> sind ohne explizite Pfeilverbindungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verankerung des Top-Level-Pakets <code>AbstractPlatform</code> zur Abstraktion gemeinsamer Plattformkonzepte zwischen Classic Platform und Adaptive Platform. Werkzeuge und Metamodell-Parser müssen das Paket im Wurzelschema und in den Namensräumen als standardisiertes Top-Level-Paket berücksichtigen.</p>"}, {"id": "FIG-a101643e7a503e84", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur statischen Metamodell-Topologie und Architektur-Strukturierung der AUTOSAR-Spezifikation. Das Diagramm illustriert die Zerlegung des Gesamtsystems in fachliche Top-Level-Template-Pakete sowie deren strukturelle Interdependenzen und Schichtenbeziehungen innerhalb des AUTOSAR-Metamodells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Metamodell-Pakete:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zur Modellwurzel <code>AUTOSAR</code>)\n</li><li><code>GenericStructure</code> (mit Notiz zur universellen Metaklassenaggregation)\n</li><li><code>CommonStructure</code>\n</li><li>Plattform- und Template-Pakete: <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>DiagnosticExtract</code>, <code>AdaptivePlatform</code>\n</li><li>Übergreifende und plattformneutrale Pakete: <code>AbstractPlatform</code> (unten links), <code>StandardizationTemplate</code>, <code>FeatureModelTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Abhängigkeiten und Verwendungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>AdaptivePlatform</code> nutzt <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><code>DiagnosticExtract</code> nutzt <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>SWComponentTemplate</code> nutzt <code>CommonStructure</code>, <code>SystemTemplate</code>, <code>EcuResourceTemplate</code> und <code>BswModuleTemplate</code>; <code>SystemTemplate</code> und <code>EcuResourceTemplate</code> verweisen ebenfalls auf <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> und <code>CommonStructure</code> besitzen wechselseitig gerichtete Pfeile; <code>SystemTemplate</code> nutzt zudem <code>EcuResourceTemplate</code> und <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> nutzt <code>SystemTemplate</code>, <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>BswModuleTemplate</code>.\n</li><li><code>BswModuleTemplate</code> nutzt <code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> und <code>ECUCDescriptionTemplate</code>.\n</li><li><code>AbstractPlatform</code>, <code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> sind ohne explizite Pfeilverbindungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Paketdiagramm zeigt die Abbildung keine dynamischen Ausführungsabläufe, Nachrichtenflüsse oder Zustandsübergänge zur Laufzeit. Es definiert die statische Dekomposition, Schichtung und Entwurfszeitabhängigkeiten zwischen den Metamodell-Paketen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Verankerung des Top-Level-Pakets <code>AbstractPlatform</code> zur Abstraktion gemeinsamer Plattformkonzepte zwischen Classic Platform und Adaptive Platform. Werkzeuge und Metamodell-Parser müssen das Paket im Wurzelschema und in den Namensräumen als standardisiertes Top-Level-Paket berücksichtigen.</p>"}], "trans": [{"from": "FIG-a5c9a69a72f2ec9f", "to": "FIG-24228ee64b6300b3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Pakete <code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> unten links hinzugefügt (ohne explizit eingezeichnete Abhängigkeitspfeile).\n</li><li>Das erläuternde Kommentarfeld zu <code>GenericStructure</code> („All other top-level packages aggregate meta-classes from &#x27;Generic Structure&#x27;“) wurde von links nach rechts neben das Paket verschoben.\n</li></ul>"}, {"from": "FIG-24228ee64b6300b3", "to": "FIG-1f628baae465cda6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Paket <code>DiagnosticExtract</code> hinzugefügt, mit gerichteten Abhängigkeitspfeilen (<code>&lt;&lt;use&gt;&gt;</code> / Aggregation) auf <code>SystemTemplate</code> und <code>SWComponentTemplate</code>.\n</li><li>Paket <code>ECUResourceTemplate</code> redaktionell umbenannt in <code>EcuResourceTemplate</code>.\n</li><li>Paket <code>FeatureModelTemplate</code> aus der linken unteren Ecke in die rechte untere Ecke verschoben.\n</li></ul>"}, {"from": "FIG-1f628baae465cda6", "to": "FIG-18b39087236dba09", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Paket <code>AdaptivePlatform</code> hinzugefügt, mit ausgehenden gerichteten Abhängigkeitspfeilen auf <code>SystemTemplate</code>, <code>SWComponentTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li>Gerichtete Abhängigkeit (<code>&lt;&lt;use&gt;&gt;</code>) von <code>SWComponentTemplate</code> auf <code>SystemTemplate</code> ergänzt.\n</li><li>Bisher bidirektionale Abhängigkeit zwischen <code>CommonStructure</code> und <code>SystemTemplate</code> aufgespalten in zwei parallele, gegenläufige vertikale Pfeile (<code>SystemTemplate</code> -&gt; <code>CommonStructure</code> und <code>CommonStructure</code> -&gt; <code>SystemTemplate</code>).\n</li><li>Bisher bidirektionale Abhängigkeit zwischen <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code> aufgespalten in zwei getrennte Pfeile (<code>BswModuleTemplate</code> -&gt; <code>ECUCDescriptionTemplate</code> und <code>ECUCDescriptionTemplate</code> -&gt; <code>BswModuleTemplate</code>).\n</li></ul>"}, {"from": "FIG-18b39087236dba09", "to": "FIG-c7110fe479811a02", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c7110fe479811a02", "to": "FIG-9408da1e4f0cdaae", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9408da1e4f0cdaae", "to": "FIG-7bbdd92765f5ecdc", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Paket <code>AbstractPlatform</code> ganz unten links hinzugefügt (ohne explizit eingezeichnete Abhängigkeitspfeile).\n</li></ul>"}, {"from": "FIG-7bbdd92765f5ecdc", "to": "FIG-a101643e7a503e84", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
